CREATE TABLE rm_accounting_approval_policy_events (
 id INTEGER PRIMARY KEY,
 scope_kind TEXT NOT NULL CHECK(scope_kind IN ('workspace','company')),
 company_slug TEXT CHECK(company_slug IS NULL OR length(company_slug) BETWEEN 1 AND 120),
 risk_class TEXT NOT NULL CHECK(risk_class IN ('normal','elevated')),
 review_mode TEXT NOT NULL CHECK(review_mode IN ('sole_authorized_bookkeeper','independent_reviewer')),
 version INTEGER NOT NULL CHECK(version>0),
 prior_event_hash TEXT,
 event_hash TEXT NOT NULL UNIQUE CHECK(length(event_hash)=64 AND event_hash NOT GLOB '*[^0-9a-f]*'),
 actor TEXT NOT NULL CHECK(length(trim(actor)) BETWEEN 3 AND 160),
 principal_id TEXT NOT NULL CHECK(length(trim(principal_id)) BETWEEN 1 AND 160),
 created_at TEXT NOT NULL,
 CHECK((scope_kind='workspace' AND company_slug IS NULL) OR (scope_kind='company' AND company_slug IS NOT NULL)),
 UNIQUE(scope_kind,company_slug,risk_class,version)
);
CREATE VIEW rm_current_accounting_approval_policies AS SELECT e.* FROM rm_accounting_approval_policy_events e JOIN (SELECT scope_kind,company_slug,risk_class,MAX(version) version FROM rm_accounting_approval_policy_events GROUP BY scope_kind,company_slug,risk_class) c ON c.scope_kind=e.scope_kind AND c.company_slug IS e.company_slug AND c.risk_class=e.risk_class AND c.version=e.version;
CREATE INDEX rm_accounting_approval_policy_scope ON rm_accounting_approval_policy_events(scope_kind,company_slug,risk_class,version DESC);
CREATE TRIGGER rm_accounting_approval_policy_events_no_update BEFORE UPDATE ON rm_accounting_approval_policy_events BEGIN SELECT RAISE(ABORT,'accounting approval policy events are append-only'); END;
CREATE TRIGGER rm_accounting_approval_policy_events_no_delete BEFORE DELETE ON rm_accounting_approval_policy_events BEGIN SELECT RAISE(ABORT,'accounting approval policy events are append-only'); END;
